#!/usr/bin/env python3
# =====================================================================
#  apply_opposite_sides.py  —  fence BROKER_TRUTH_OPPOSITE_20261114
#  REQUIRES apply_broker_truth.py (BROKER_TRUTH_20261114) first.
#
#  ⚠ LIVE ORDER PATH — strike choice of NEW legs (LIVE mode only) for
#  Icarus's adjustment, Timberwolf's sell + hedge, Velvet's short + wing.
#
#  The question: Icarus's L1 stops out and it BUYS an adjustment — what if
#  Velvet or Timberwolf is SHORT that same contract?
#
#  Two strategies on the SAME side of a contract simply add up (handled by
#  BROKER_TRUTH). On OPPOSITE sides they cancel at the broker: Icarus long
#  195 + Timberwolf short 130 shows as +65, and NO margin is held for the
#  short. Whichever leg is closed later turns the netted quantity into a
#  fresh position the broker must margin — Icarus selling its 195 would
#  need margin for a brand-new 130 short, and that exit can be REJECTED for
#  funds (the account already refused a 195 sell on 12 Nov).
#
#   1. AVOID IT (LIVE only; paper keeps the backtest's pick):
#      * Icarus's adjustment skips a contract another strategy is short
#        and takes the next candidate under its cap;
#      * Timberwolf does not sell a contract another strategy is long (nor
#        hedge with one another strategy is short) — next candidate;
#      * Velvet steps one strike further OTM (max 3) instead of selling a
#        contract another strategy is long; its wing skips shorted ones.
#      Each skip is written to the audit log with the other strategy.
#   2. IF IT HAPPENS ANYWAY (an overlap from before this build, a restart):
#      nothing changes in the rules — a netted contract is "shared", so
#      every strategy closes exactly its own quantity on its own orders and
#      GTTs. Proven end to end in the fleet suite.
#
#   broker_truth.py   LEDGER.opposite(symbol, me, side)
#   ic_group_manager.py / tma2_trade_manager.py / vet_manager.py   the skips
#   test_fleet_live.py  394 checks (+32): adjustment vs shorts, shorts vs an
#     adjustment, the netted case with a GTT stop on it, and the Kite login
#     landing before the open with empty answers
#
#  Run ONLY this script, outside market hours:
#     cd ~/dev/scalp-app && python3 apply_opposite_sides.py
#  Options: --repo PATH  --skip-tests  --allow-dirty  --rollback
#  Then: ./desktop/build-scalp.sh both, restart the app.
# =====================================================================
import base64, hashlib, json, os, py_compile, shutil, subprocess, sys, tempfile, zlib

FENCE = "BROKER_TRUTH_OPPOSITE_20261114"
ITEMS = json.loads(r'''[{"path": "backend/app/execution/broker_truth.py", "orig": "4913c6fbf79878e201e088fe057b6a913ca7a4716d213f8f68934de69eba07f5", "new": "580de64536d6472c76099d56db4ef9880135640209591f2df248e21f99f5adfa", "blob": ""}, {"path": "backend/app/engine/ic/ic_group_manager.py", "orig": "1ea7c00525811f308ab5669636be529f38cb2b0be469d808e68629165adaf03f", "new": "e618c12e3ea3dccdc512d4364740c87e40c444e4d1d81c84b9bd12fe8ab02dae", "blob": ""}, {"path": "backend/app/engine/tma2/tma2_trade_manager.py", "orig": "453e97991de2568a3fc6b2d62b04c597b3dd0b5ce2d496e1c1a88a5bfb8bd462", "new": "48ebca2fabf3cd8b0331015527654686abc4e1021256f86845c91a512794f175", "blob": ""}, {"path": "backend/app/engine/vet/vet_manager.py", "orig": "26da4cf41bd3faaff8f9929c3690171245e83bcb98faaf56ad01c97c8ac513ea", "new": "fd452006d6487040382cad6ffeab8066975ec95d1b8190e7fb46528655c54edc", "blob": ""}, {"path": "backend/app/engine/test_fleet_live.py", "orig": "1d0fba3f6d7de1946ce8549d0e76d99f8f7ce633bf26ce78f6782f102a8b4a44", "new": "b2d2d94026b8e1e2ab6b9ecba765261be4cdfccc9336ae3de89a4ee5fd5000d6", "blob": ""}]''')
BUILD_COPIES = {"backend/": "desktop/src-tauri/backend/", "frontend/": "desktop/src-tauri/frontend/"}
TESTS = ["app/execution/test_broker_truth.py", "app/engine/test_fleet_live.py",
         "app/engine/ic/test_ic_gtt_strict.py",          # runs the IC suites one by one
         "app/engine/tma2/test_tma2_e2e.py", "app/engine/tma2/test_tma2_entry_paths.py",
         "app/engine/tma2/test_tma2_exit_paths.py",
         "app/engine/vet/test_vet_e2e.py", "app/engine/vet/test_vet_manager.py",
         "app/engine/vet/test_vet_wing_far.py", "app/engine/vet/test_vet_live_confirm.py",
         "app/engine/test_entry_fast_confirm.py"]


def sha(b):
    return hashlib.sha256(b).hexdigest()


def say(m):
    print(m, flush=True)


def die(m):
    say(f"\n✗ ABORTED — {m}\n  Nothing was changed.")
    sys.exit(1)


args = sys.argv[1:]
repo = os.path.abspath(os.path.expanduser(args[args.index("--repo") + 1])) if "--repo" in args else os.getcwd()
if not os.path.isdir(os.path.join(repo, "backend", "app")):
    alt = os.path.expanduser("~/dev/scalp-app")
    if os.path.isdir(os.path.join(alt, "backend", "app")):
        repo = alt
    else:
        die(f"{repo} is not the scalp-app repo (no backend/app) — pass --repo PATH")
say(f"repo: {repo}\nfence: {FENCE}")

# ── prerequisite: apply_broker_truth.py (BROKER_TRUTH_20261114)
if "--rollback" not in args and not os.path.exists(
        os.path.join(repo, "backend", "app", "execution", "broker_truth.py")):
    die("run apply_broker_truth.py first — this script builds on BROKER_TRUTH_20261114")


def targets():
    """(item, absolute path, is_build_copy)"""
    out = []
    for it in ITEMS:
        out.append((it, os.path.join(repo, it["path"]), False))
        for a, b in BUILD_COPIES.items():
            if it["path"].startswith(a):
                p = os.path.join(repo, b + it["path"][len(a):])
                if os.path.isdir(os.path.dirname(p)):
                    out.append((it, p, True))
    return out


# ── rollback mode ────────────────────────────────────────────────────
if "--rollback" in args:
    n = 0
    for it, p, _ in targets():
        bak = p + ".bak-" + FENCE
        if os.path.exists(bak):
            shutil.copy2(bak, p)
            os.remove(bak)
            n += 1
        elif it["orig"] is None and os.path.exists(p):
            with open(p, "rb") as f:
                if sha(f.read()) == it["new"]:
                    os.remove(p)
                    n += 1
    say(f"rolled back {n} file(s)")
    sys.exit(0)

# ── 1. state of every target ─────────────────────────────────────────
plan, done, skipped = [], 0, []
for it, p, build in targets():
    cur = open(p, "rb").read() if os.path.exists(p) else None
    cs = sha(cur) if cur is not None else None
    rel = os.path.relpath(p, repo)
    if cs == it["new"]:
        done += 1
        continue
    if cs == it["orig"]:
        plan.append((it, p, cur, build))
        continue
    if build:
        skipped.append(rel)              # a stale build copy — the build re-syncs it
        continue
    if cur is None:
        die(f"{rel} is missing")
    die(f"{rel} differs from GitHub main and from the patched version — local edits? "
        f"(commit/stash them or pull main, then re-run)")
if not plan:
    say(f"✓ already applied ({done} file(s) carry {FENCE}) — nothing to do")
    sys.exit(0)

# ── 2. git status: an uncommitted change on a target is a stop sign ──
if "--allow-dirty" not in args:
    try:
        rels = [os.path.relpath(p, repo) for _, p, _, b in plan if not b]
        st = subprocess.run(["git", "status", "--porcelain", "--"] + rels, cwd=repo,
                            capture_output=True, text=True, timeout=30).stdout
        dirty = [l for l in st.splitlines() if l[:2].strip() and not l.startswith("??")]
        if dirty:
            die("uncommitted changes on target files:\n  " + "\n  ".join(dirty) + "\n  (re-run with --allow-dirty to override)")
    except FileNotFoundError:
        say("  (git not found — skipping the status check)")

# ── 3. decode + compile every payload before writing anything ───────
tmp = tempfile.mkdtemp(prefix="opposite_sides_")
blobs = {}
for it in ITEMS:
    b = zlib.decompress(base64.b64decode(it["blob"]))
    if sha(b) != it["new"]:
        die(f"payload for {it['path']} is corrupt")
    blobs[it["path"]] = b
    if it["path"].endswith(".py"):
        f = os.path.join(tmp, os.path.basename(it["path"]))
        open(f, "wb").write(b)
        try:
            py_compile.compile(f, doraise=True)
        except py_compile.PyCompileError as e:
            die(f"payload {it['path']} does not compile: {e}")
say(f"payloads verified and compiled ({len(ITEMS)} files)")

# ── 4. write, all or nothing ─────────────────────────────────────────
written = []


def restore():
    for p, old in reversed(written):
        try:
            if old is None:
                os.remove(p)
            else:
                open(p, "wb").write(old)
            bak = p + ".bak-" + FENCE
            if os.path.exists(bak):
                os.remove(bak)
        except Exception as e:
            say(f"  !! could not restore {p}: {e}")


try:
    for it, p, cur, build in plan:
        if cur is not None:
            open(p + ".bak-" + FENCE, "wb").write(cur)
        t = p + ".tmp-" + FENCE
        open(t, "wb").write(blobs[it["path"]])
        os.replace(t, p)
        written.append((p, cur))
        say(f"  wrote {os.path.relpath(p, repo)}{'  (build copy)' if build else ''}")
except Exception as e:
    restore()
    die(f"write failed ({e!r}) — everything restored")
for s_ in skipped:
    say(f"  skipped stale build copy {s_} (the next build re-syncs it)")

# ── 5. tests ─────────────────────────────────────────────────────────
backend = os.path.join(repo, "backend")
py = next((c for c in (os.path.join(backend, "venv", "bin", "python"), os.path.join(backend, ".venv", "bin", "python"),
                       os.path.join(repo, "venv", "bin", "python"), os.path.join(repo, ".venv", "bin", "python"))
           if os.path.exists(c)), sys.executable)
if "--skip-tests" in args:
    say("tests skipped (--skip-tests)")
else:
    say(f"running tests with {py}")
    env = dict(os.environ, PYTHONPATH=backend)
    failed, envmiss = [], []
    for t in TESTS:
        if not os.path.exists(os.path.join(backend, t)):
            continue
        try:
            r = subprocess.run([py, t], cwd=backend, env=env, capture_output=True, text=True, timeout=600)
            outp = (r.stdout or "") + (r.stderr or "")
        except subprocess.TimeoutExpired:
            r, outp = None, "timeout"
        last = (outp.strip().splitlines() or [""])[-1]
        if r is not None and r.returncode == 0:
            say(f"  ✓ {t}  {last}")
        elif "ModuleNotFoundError" in outp and "No module named 'app" not in outp:
            envmiss.append(t)
            say(f"  ? {t}  could not run here: {last}")
        else:
            failed.append(t)
            say(f"  ✗ {t}\n" + "\n".join("      " + l for l in outp.strip().splitlines()[-25:]))
    if failed:
        restore()
        die("tests failed: " + ", ".join(failed) + " — every file restored")
    if envmiss:
        say("  note: some suites need the backend's Python packages; re-run them with that Python")

shutil.rmtree(tmp, ignore_errors=True)
say(f"\n✓ {FENCE} applied ({len(written)} file(s)). Next: ./desktop/build-scalp.sh both, then restart the app.")
say("  Undo: python3 apply_opposite_sides.py --rollback")
